package com.moodcanvas.util;
import org.w3c.dom.*;import org.xml.sax.InputSource;import javax.xml.parsers.*;import javax.xml.xpath.*;import java.io.*;import java.util.*;
public final class XMLParser {private XMLParser(){}private static Document parse(String xml)throws Exception{DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);f.setFeature("http://xml.org/sax/features/external-general-entities",false);f.setFeature("http://xml.org/sax/features/external-parameter-entities",false);return f.newDocumentBuilder().parse(new InputSource(new StringReader(xml)));}public static List<Map<String,String>> parseArtworkXML(String xml){List<Map<String,String>>out=new ArrayList<>();try{Document d=parse(xml);XPath x=XPathFactory.newInstance().newXPath();NodeList ns=(NodeList)x.evaluate("//artwork",d,XPathConstants.NODESET);for(int i=0;i<ns.getLength();i++){Node n=ns.item(i);Map<String,String> m=new LinkedHashMap<>();m.put("id",n.getAttributes().getNamedItem("id").getNodeValue());for(String k:List.of("title","artist","imageURL","museum","mood"))m.put(k,x.evaluate("./"+k+"/text()",n));out.add(m);}}catch(Exception ignored){}return out;}public static String buildMoodResponseXML(List<Map<String,String>>arts,String mood,String term){StringBuilder b=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><moodResponse><mood>").append(esc(mood)).append("</mood><searchTerm>").append(esc(term)).append("</searchTerm>");for(Map<String,String>a:arts){b.append("<artwork id=\"").append(esc(a.get("id"))).append("\">");for(String k:List.of("title","artist","imageURL","museum","mood"))b.append('<').append(k).append('>').append(esc(a.get(k))).append("</").append(k).append('>');b.append("</artwork>");}return b.append("</moodResponse>").toString();}private static String esc(String s){if(s==null)return "";return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&apos;");}}
